// Grammar
// =============================================================================

/// Node spans and rule ids are recorded (`@schema` or `--spans`).
pub const nodeStore = true;
/// Element extents are kept for side-band labels and nested nodes.
const elemEnds = true;
/// Lists keep trailing nils: positions are fixed by the schema.
const keepTrailingNils = true;
const hasTrivia = false;
const hasRepair = false;
const numSymbols = 186;
const endSymbol: u16 = 1;
const errorSymbol: u16 = 2;

fn tokenToSymbol(_: *BaseParser, token: Token) u16 {
    return switch (token.cat) {
        .@"eof" => 1,
        .@"newline" => 70,
        .@"indent" => 71,
        .@"outdent" => 72,
        .@"ident" => 74,
        .@"post_if" => 75,
        .@"new" => 79,
        .@"drop_stmt" => 80,
        .@"return" => 81,
        .@"break" => 82,
        .@"continue" => 83,
        .@"defer" => 84,
        .@"errdefer" => 85,
        .@"raw" => 86,
        .@"pub" => 97,
        .@"use" => 98,
        .@"fun" => 99,
        .@"sub" => 100,
        .@"lparen_call" => 104,
        .@"pre" => 106,
        .@"read_pfx" => 107,
        .@"write_pfx" => 108,
        .@"kwarg_name" => 109,
        .@"enum" => 110,
        .@"error" => 111,
        .@"struct" => 112,
        .@"type" => 113,
        .@"drop" => 114,
        .@"test" => 117,
        .@"string_dq" => 118,
        .@"string_sq" => 119,
        .@"extern" => 120,
        .@"share_pfx" => 121,
        .@"integer" => 125,
        .@"suffix_q" => 129,
        .@"suffix_bang" => 130,
        .@"catch" => 132,
        .@"bar_capture" => 133,
        .@"ternary_if" => 134,
        .@"else" => 135,
        .@"or" => 136,
        .@"and" => 137,
        .@"not" => 138,
        .@"move_pfx" => 140,
        .@"as" => 141,
        .@"if" => 142,
        .@"while" => 143,
        .@"for" => 144,
        .@"in" => 145,
        .@"match" => 146,
        .@"minus_prefix" => 149,
        .@"true" => 150,
        .@"false" => 151,
        .@"dot_lit" => 152,
        .@"bar_empty" => 153,
        .@"clone_pfx" => 154,
        .@"lbracket_index" => 155,
        .@"real" => 156,
        .@"colon" => 73,
        .@"assign" => 78,
        .@"rparen" => 102,
        .@"comma" => 103,
        .@"lparen" => 105,
        .@"tilde" => 122,
        .@"lbracket" => 123,
        .@"rbracket" => 124,
        .@"dot" => 131,
        .@"at" => 157,
        .@"lt" => 171,
        .@"gt" => 172,
        .@"bar" => 176,
        .@"caret" => 177,
        .@"ampersand" => 178,
        .@"plus" => 181,
        .@"minus" => 182,
        .@"star" => 183,
        .@"slash" => 184,
        .@"percent" => 185,
        .@"fixed_assign" => 76,
        .@"move_assign" => 77,
        .@"plus_assign" => 87,
        .@"minus_assign" => 88,
        .@"star_assign" => 89,
        .@"slash_assign" => 90,
        .@"percent_assign" => 91,
        .@"amp_assign" => 92,
        .@"bar_assign" => 93,
        .@"caret_assign" => 94,
        .@"lshift_assign" => 95,
        .@"rshift_assign" => 96,
        .@"arrow" => 101,
        .@"fat_arrow" => 147,
        .@"dotdot" => 148,
        .@"eq" => 169,
        .@"ne" => 170,
        .@"le" => 173,
        .@"ge" => 174,
        .@"nullish" => 175,
        .@"lshift" => 179,
